export function parseDuration(text: string): number {
  const units: Record<string, number> = { s: 1, m: 60, h: 3600, d: 86400 };
  const cleaned = text.replace(/\s+/g, '');
  const re = /^(\d+([smhd]))+$/;
  if (!cleaned || !re.test(cleaned)) throw new Error(`invalid duration: ${text}`);
  let total = 0;
  for (const [, n, u] of cleaned.matchAll(/(\d+)([smhd])/g)) total += Number(n) * units[u];
  return total;
}
